CREATE TABLE BILL_CALCULATION_SNAPSHOT (SNAPSHOT_ID VARCHAR2(36) PRIMARY KEY, BILL_ID VARCHAR2(36) NOT NULL UNIQUE, PRODUCT_VERSION VARCHAR2(30) NOT NULL, INTEREST_POLICY_VERSION VARCHAR2(30) NOT NULL, RATE_SNAPSHOT NUMBER(9,6) NOT NULL, FEE_RULES_JSON CLOB, CALCULATED_AT TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT FK_BILL_SNAPSHOT_BILL FOREIGN KEY (BILL_ID) REFERENCES BILL(BILL_ID));
